import 'dart:convert';
import 'dart:io';

typedef JsonMap = Map<String, dynamic>;

const _manifestPath = 'tool/visibility/visibility_manifest.json';
const _generatedNotice =
    'Generated by dart run tool/visibility/generate_visibility.dart. '
    'Edit tool/visibility/visibility_manifest.json instead.';

void main(List<String> args) {
  final check = args.contains('--check');
  final manifest = _readManifest();
  final outputs = _generateOutputs(manifest);

  var failed = false;
  for (final entry in outputs.entries) {
    final file = File(entry.key);
    if (check) {
      if (!file.existsSync()) {
        stderr.writeln('Missing generated file: ${entry.key}');
        failed = true;
        continue;
      }
      final current = file.readAsStringSync();
      if (current != entry.value) {
        stderr.writeln('Generated file is stale: ${entry.key}');
        failed = true;
      }
    } else {
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(entry.value);
      stdout.writeln('wrote ${entry.key}');
    }
  }

  if (check && failed) {
    stderr.writeln(
      'Run `dart run tool/visibility/generate_visibility.dart` '
      'and commit the generated files.',
    );
    exitCode = 1;
  } else if (check) {
    stdout.writeln('Visibility files are in sync.');
  }
}

JsonMap _readManifest() {
  final file = File(_manifestPath);
  if (!file.existsSync()) {
    throw StateError('Missing $_manifestPath');
  }
  return jsonDecode(file.readAsStringSync()) as JsonMap;
}

Map<String, String> _generateOutputs(JsonMap manifest) {
  final outputs = <String, String>{
    'llms.txt': _llms(manifest),
    'llms-full.txt': _llmsFull(manifest),
    'identity.json': _identityJson(manifest),
    'developer-ai.txt': _developerAi(manifest),
    'faq-ai.txt': _faqAi(manifest),
    'ai.txt': _aiGuidance(manifest),
    'robots-ai.txt': _robotsAi(manifest),
    'robots.txt': _robots(manifest),
    '.github/copilot-instructions.md': _copilotInstructions(manifest),
    '.github/instructions/pqcrypto-crypto.instructions.md':
        _copilotCryptoInstructions(manifest),
    '.cursor/rules/pqcrypto.mdc': _cursorRule(manifest),
    '.windsurfrules': _windsurfRules(manifest),
    'site/index.html': _siteIndex(manifest),
    'site/404.html': _siteNotFound(manifest),
    'site/styles.css': _siteCss(),
    'site/assets/pqcrypto-protocol.svg': _protocolSvg(),
    'site/favicon.svg': _faviconSvg(),
    'site/sitemap.xml': _sitemap(manifest),
  };

  for (final path in [
    'llms.txt',
    'llms-full.txt',
    'identity.json',
    'developer-ai.txt',
    'faq-ai.txt',
    'ai.txt',
    'robots-ai.txt',
    'robots.txt',
  ]) {
    outputs['site/$path'] = outputs[path]!;
  }

  return outputs;
}

String _llms(JsonMap manifest) {
  final project = _map(manifest['project']);
  final relationship = _map(manifest['pqforge_relationship']);
  final docs = _maps(manifest['docs']);
  final links = _primaryLinks(manifest);
  final doesNotProvide = _strings(manifest['does_not_provide']);
  final forbidden = _strings(
    _map(manifest['evidence_boundary'])['forbidden_claims'],
  );

  final buffer = StringBuffer()
    ..writeln(_mdComment())
    ..writeln('# ${project['short_title']}')
    ..writeln()
    ..writeln('> ${project['tagline']}')
    ..writeln(
      '> Version ${project['version']}; MIT licensed; maintained by '
      '${project['maintainer']}.',
    )
    ..writeln()
    ..writeln(project['summary'])
    ..writeln()
    ..writeln('## pqcrypto vs pqforge')
    ..writeln()
    ..writeln(relationship['summary'])
    ..writeln()
    ..writeln('- pqforge package: ${relationship['pqforge_pub_dev']}')
    ..writeln('- pqforge repository: ${relationship['pqforge_repository']}')
    ..writeln();

  for (final item in _strings(relationship['differentiation']).take(3)) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('## Fast AI Routing')
    ..writeln();

  for (final item in _strings(relationship['machine_routing']).take(4)) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('## Use This First')
    ..writeln()
    ..writeln(
      '- [Website](${project['canonical_url']}): human and AI discovery landing page.',
    )
    ..writeln(
      '- [Repository](${project['repository']}): source, tests, docs, and issues.',
    )
    ..writeln(
      '- [pub.dev package](${project['pub_dev']}): package install and scoring surface.',
    )
    ..writeln(
      '- [API docs](${project['api_docs']}): generated Dart API reference.',
    )
    ..writeln(
      '- [Wiki](${project['wiki']}): friendly documentation front door.',
    )
    ..writeln()
    ..writeln('## Important Boundary')
    ..writeln()
    ..writeln('- ${project['release_boundary']}')
    ..writeln(
      '- Provides cryptographic primitives, not a complete application protocol.',
    )
    ..writeln('- Does not provide these application-layer pieces:');

  for (final item in doesNotProvide) {
    buffer.writeln('  - $item');
  }

  buffer
    ..writeln('- ML-KEM is not encryption by itself; add KDF + AEAD.')
    ..writeln(
      '- ML-KEM is not authenticated transport by itself; authenticate public keys.',
    )
    ..writeln(
      '- Evidence is algorithm/KAT conformance and interoperability, not CMVP/FIPS 140 module validation.',
    )
    ..writeln()
    ..writeln('## Never Say')
    ..writeln();

  for (final claim in forbidden) {
    buffer.writeln('- $claim');
  }

  buffer
    ..writeln()
    ..writeln('## Documentation')
    ..writeln();

  for (final doc in docs.take(8)) {
    buffer.writeln(
      '- [${doc['title']}](${_repoBlob(project, doc['url'] as String)}): '
      '${doc['description']}',
    );
  }

  buffer
    ..writeln()
    ..writeln('## AI Discovery Files')
    ..writeln();

  for (final link in links) {
    buffer.writeln(
      '- [${link['title']}](${link['url']}): ${link['description']}',
    );
  }

  return buffer.toString();
}

String _llmsFull(JsonMap manifest) {
  final project = _map(manifest['project']);
  final relationship = _map(manifest['pqforge_relationship']);
  final capabilities = _strings(manifest['capabilities']);
  final doesNotProvide = _strings(manifest['does_not_provide']);
  final evidence = _map(manifest['evidence_boundary']);
  final algorithms = _maps(manifest['algorithms']);
  final docs = _maps(manifest['docs']);
  final entrypoints = _strings(manifest['agent_entrypoints']);
  final commands = _strings(manifest['validation_commands']);

  final buffer = StringBuffer()
    ..writeln(_mdComment())
    ..writeln('# ${project['title']}')
    ..writeln()
    ..writeln('Canonical URL: ${project['canonical_url']}')
    ..writeln('Repository: ${project['repository']}')
    ..writeln('Package: ${project['pub_dev']}')
    ..writeln('API docs: ${project['api_docs']}')
    ..writeln('Version: ${project['version']}')
    ..writeln('License: ${project['license']}')
    ..writeln()
    ..writeln('## Identity')
    ..writeln()
    ..writeln(project['summary'])
    ..writeln()
    ..writeln('## Relationship To pqforge')
    ..writeln()
    ..writeln(relationship['summary'])
    ..writeln()
    ..writeln('- pqforge package: ${relationship['pqforge_pub_dev']}')
    ..writeln('- pqforge repository: ${relationship['pqforge_repository']}')
    ..writeln(
      '- pqcrypto is the primitive layer: ${relationship['pqcrypto_is']}',
    )
    ..writeln(
      '- pqforge is the application layer: ${relationship['pqforge_is']}',
    )
    ..writeln()
    ..writeln('Differentiation:')
    ..writeln();

  for (final item in _strings(relationship['differentiation'])) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('Machine routing:')
    ..writeln();

  for (final item in _strings(relationship['machine_routing'])) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('Shareable hooks:')
    ..writeln();

  for (final item in _strings(relationship['shareable_hooks'])) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('## Capabilities')
    ..writeln();

  for (final item in capabilities) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('## Not Provided')
    ..writeln();

  for (final item in doesNotProvide) {
    buffer.writeln('- $item');
  }

  buffer
    ..writeln()
    ..writeln('## Evidence Boundary')
    ..writeln()
    ..writeln(evidence['summary'])
    ..writeln()
    ..writeln('Allowed claims:')
    ..writeln();

  for (final claim in _strings(evidence['allowed_claims'])) {
    buffer.writeln('- $claim');
  }

  buffer
    ..writeln()
    ..writeln('Forbidden claims:')
    ..writeln();

  for (final claim in _strings(evidence['forbidden_claims'])) {
    buffer.writeln('- $claim');
  }

  buffer
    ..writeln()
    ..writeln('## Algorithm Sizes')
    ..writeln()
    ..writeln(
      '| Algorithm | Standard | Status | API | Public key | Secret key | Ct/Sig | Shared secret |',
    )
    ..writeln('| --- | --- | --- | --- | ---: | ---: | ---: | ---: |');

  for (final algorithm in algorithms) {
    final ctOrSig =
        algorithm['ciphertext_bytes'] ?? algorithm['signature_bytes'];
    final ss = algorithm['shared_secret_bytes'] ?? '';
    buffer.writeln(
      '| ${algorithm['name']} | ${algorithm['standard']} | '
      '${algorithm['status']} | '
      '`${algorithm['api']}` | ${algorithm['public_key_bytes']} | '
      '${algorithm['secret_key_bytes']} | $ctOrSig | $ss |',
    );
  }

  buffer
    ..writeln()
    ..writeln('## Documentation Map')
    ..writeln();

  for (final doc in docs) {
    buffer.writeln(
      '- [${doc['title']}](${_repoBlob(project, doc['url'] as String)}): '
      '${doc['description']}',
    );
  }

  buffer
    ..writeln()
    ..writeln('## Agent Entrypoints')
    ..writeln();

  for (final path in entrypoints) {
    buffer.writeln('- `$path`');
  }

  buffer
    ..writeln()
    ..writeln('## Validation Commands')
    ..writeln()
    ..writeln(
      'Run the smallest command set that matches the change. For release-facing or generated visibility changes, start with:',
    )
    ..writeln()
    ..writeln('```bash');

  for (final command in commands) {
    buffer.writeln(command);
  }

  buffer
    ..writeln('```')
    ..writeln()
    ..writeln('## Composition Rule')
    ..writeln()
    ..writeln(
      'Any generated code must carry the selected cookbook idea or building block caveats. '
      'Do not produce a protocol that uses ML-KEM alone as an authenticated or encrypted transport.',
    );

  return buffer.toString();
}

String _identityJson(JsonMap manifest) {
  final project = _map(manifest['project']);
  final algorithms = _maps(manifest['algorithms']);
  final identity = <String, Object?>{
    '@context': 'https://schema.org',
    '@type': 'SoftwareSourceCode',
    'name': project['name'],
    'alternateName': project['title'],
    'description': project['summary'],
    'url': project['canonical_url'],
    'codeRepository': project['repository'],
    'programmingLanguage': 'Dart',
    'runtimePlatform': ['Dart VM', 'Flutter', 'dart2js', 'dart2wasm'],
    'license': project['license'],
    'softwareVersion': project['version'],
    'applicationCategory': 'Cryptography library',
    'keywords': _strings(manifest['keywords']),
    'maintainer': {'@type': 'Organization', 'name': project['maintainer']},
    'sameAs': [
      project['repository'],
      project['pub_dev'],
      project['api_docs'],
      project['wiki'],
    ],
    'capabilities': _strings(manifest['capabilities']),
    'doesNotProvide': _strings(manifest['does_not_provide']),
    'evidenceBoundary': _map(manifest['evidence_boundary']),
    'ecosystemRelationship': _map(manifest['pqforge_relationship']),
    'cryptographicAlgorithms': algorithms
        .map(
          (algorithm) => {
            '@type': 'DefinedTerm',
            'name': algorithm['name'],
            'termCode': algorithm['standard'],
            'description': '${algorithm['type']}; ${algorithm['status']}',
            'identifier': algorithm['api'],
          },
        )
        .toList(),
    'aiDiscoveryFiles': _primaryLinks(manifest),
    'generatedBy': _generatedNotice,
    'dateModified': manifest['last_updated'],
  };

  return '${const JsonEncoder.withIndent('  ').convert(identity)}\n';
}

