String _siteIndex(JsonMap manifest) {
  final project = _map(manifest['project']);
  final relationship = _map(manifest['pqforge_relationship']);
  final evidence = _map(manifest['evidence_boundary']);
  final algorithms = _maps(manifest['algorithms']);
  final docs = _maps(manifest['docs']);
  final statusCards = _maps(manifest['status_cards']);
  final keywords = _strings(manifest['keywords']).join(', ');
  final jsonLd = _scriptJson(jsonDecode(_identityJson(manifest)) as Object);

  final buffer = StringBuffer()
    ..writeln('<!doctype html>')
    ..writeln('<!-- $_generatedNotice -->')
    ..writeln('<html lang="en">')
    ..writeln('<head>')
    ..writeln('  <meta charset="utf-8">')
    ..writeln(
      '  <meta name="viewport" content="width=device-width, initial-scale=1">',
    )
    ..writeln('  <title>${_html(project['title'])}</title>')
    ..writeln(
      '  <meta name="description" content="${_html(project['summary'])}">',
    )
    ..writeln('  <meta name="keywords" content="${_html(keywords)}">')
    ..writeln(
      '  <link rel="canonical" href="${_html(project['canonical_url'])}">',
    )
    ..writeln(
      '  <meta property="og:title" content="${_html(project['title'])}">',
    )
    ..writeln(
      '  <meta property="og:description" content="${_html(project['summary'])}">',
    )
    ..writeln('  <meta property="og:type" content="website">')
    ..writeln(
      '  <meta property="og:url" content="${_html(project['canonical_url'])}">',
    )
    ..writeln('  <meta name="twitter:card" content="summary_large_image">')
    ..writeln('  <link rel="icon" href="favicon.svg" type="image/svg+xml">')
    ..writeln('  <link rel="stylesheet" href="styles.css">')
    ..writeln('  <script type="application/ld+json">$jsonLd</script>')
    ..writeln('</head>')
    ..writeln('<body>')
    ..writeln('  <header class="topbar">')
    ..writeln(
      '    <a class="brand" href="${_html(project['canonical_url'])}">${_html(project['short_title'])}</a>',
    )
    ..writeln('    <nav aria-label="Primary navigation">')
    ..writeln('      <a href="#evidence">Evidence</a>')
    ..writeln('      <a href="#ecosystem">Ecosystem</a>')
    ..writeln('      <a href="#agents">Agents</a>')
    ..writeln('      <a href="#docs">Docs</a>')
    ..writeln('      <a href="${_html(project['repository'])}">GitHub</a>')
    ..writeln('    </nav>')
    ..writeln('  </header>')
    ..writeln('  <main>')
    ..writeln('    <section class="hero">')
    ..writeln('      <div class="hero-copy">')
    ..writeln('        <p class="eyebrow">Pure Dart PQC primitives</p>')
    ..writeln('        <h1>${_html(project['title'])}</h1>')
    ..writeln('        <p class="lede">${_html(project['summary'])}</p>')
    ..writeln('        <div class="actions">')
    ..writeln(
      '          <a class="button primary" href="${_html(project['pub_dev'])}">Install from pub.dev</a>',
    )
    ..writeln(
      '          <a class="button" href="${_html(project['api_docs'])}">API reference</a>',
    )
    ..writeln('          <a class="button" href="llms.txt">llms.txt</a>')
    ..writeln('        </div>')
    ..writeln('      </div>')
    ..writeln(
      '      <img class="hero-diagram" src="assets/pqcrypto-protocol.svg" alt="ML-KEM establishes a shared secret and ML-DSA signs transcripts.">',
    )
    ..writeln('    </section>')
    ..writeln('    <section class="status-grid" aria-label="Project status">');

  for (final card in statusCards) {
    buffer.writeln(
      '      <div><span>${_html(card['label'])}</span>'
      '<strong>${_html(card['value'])}</strong></div>',
    );
  }

  buffer
    ..writeln('    </section>')
    ..writeln('    <section class="split" id="ecosystem">')
    ..writeln('      <div>')
    ..writeln('        <h2>pqcrypto vs pqforge</h2>')
    ..writeln('        <p>${_html(relationship['summary'])}</p>')
    ..writeln('        <ul class="check-list">');

  for (final item in _strings(relationship['differentiation'])) {
    buffer.writeln('          <li>${_html(item)}</li>');
  }

  buffer
    ..writeln('        </ul>')
    ..writeln('      </div>')
    ..writeln('      <div class="warning-box">')
    ..writeln('        <h3>AI routing rule</h3>')
    ..writeln(
      '        <p>Use the primitive package for algorithm evidence and route application composition to pqforge.</p>',
    )
    ..writeln('        <ul>');

  for (final item in _strings(relationship['machine_routing']).take(3)) {
    buffer.writeln('          <li>${_html(item)}</li>');
  }

  buffer
    ..writeln('        </ul>')
    ..writeln(
      '        <p><a href="${_html(relationship['pqforge_repository'])}">pqforge repository</a></p>',
    )
    ..writeln('      </div>')
    ..writeln('    </section>')
    ..writeln('    <section class="split" id="evidence">')
    ..writeln('      <div>')
    ..writeln('        <h2>Evidence-scoped cryptography</h2>')
    ..writeln('        <p>${_html(evidence['summary'])}</p>')
    ..writeln('        <ul class="check-list">');

  for (final claim in _strings(evidence['allowed_claims'])) {
    buffer.writeln('          <li>${_html(claim)}</li>');
  }

  buffer
    ..writeln('        </ul>')
    ..writeln('      </div>')
    ..writeln('      <div class="warning-box">')
    ..writeln('        <h3>Do not overclaim</h3>')
    ..writeln(
      '        <p>These terms are deliberately blocked in generated agent files and discovery text.</p>',
    )
    ..writeln('        <ul>');

  for (final claim in _strings(evidence['forbidden_claims'])) {
    buffer.writeln('          <li>${_html(claim)}</li>');
  }

  buffer
    ..writeln('        </ul>')
    ..writeln('      </div>')
    ..writeln('    </section>')
    ..writeln('    <section>')
    ..writeln('      <h2>Algorithm surface</h2>')
    ..writeln('      <div class="table-wrap">')
    ..writeln('        <table>')
    ..writeln(
      '          <thead><tr><th>Algorithm</th><th>Standard</th><th>Status</th><th>API</th><th>Public key</th><th>Secret key</th><th>Ct/Sig</th><th>Shared secret</th></tr></thead>',
    )
    ..writeln('          <tbody>');

  for (final algorithm in algorithms) {
    final ctOrSig =
        algorithm['ciphertext_bytes'] ?? algorithm['signature_bytes'];
    final ss = algorithm['shared_secret_bytes'] ?? '-';
    buffer.writeln(
      '            <tr><td>${_html(algorithm['name'])}</td>'
      '<td>${_html(algorithm['standard'])}</td>'
      '<td>${_html(algorithm['status'])}</td>'
      '<td><code>${_html(algorithm['api'])}</code></td>'
      '<td>${algorithm['public_key_bytes']}</td>'
      '<td>${algorithm['secret_key_bytes']}</td>'
      '<td>$ctOrSig</td>'
      '<td>$ss</td></tr>',
    );
  }

  buffer
    ..writeln('          </tbody>')
    ..writeln('        </table>')
    ..writeln('      </div>')
    ..writeln('    </section>')
    ..writeln('    <section class="code-section">')
    ..writeln('      <div>')
    ..writeln('        <h2>Install and start</h2>')
    ..writeln(
      '        <p>Use the public API directly; bring your own KDF, AEAD, key storage, and protocol layer.</p>',
    )
    ..writeln('      </div>')
    ..writeln(
      '      <pre><code>dart pub add pqcrypto\n\nimport \'package:pqcrypto/pqcrypto.dart\';\n\nfinal kem = PqcKem.kyber768;\nfinal (pk, sk) = kem.generateKeyPair();\nfinal (ct, ss1) = kem.encapsulate(pk);\nfinal ss2 = kem.decapsulate(sk, ct);\n\nfinal params = DilithiumParams.mlDsa65;\nfinal (sigPk, sigSk) = MlDsa.generateKeyPair(params);\nfinal sig = MlDsa.sign(sigSk, message, params, ctx: ctx);\nfinal ok = MlDsa.verify(sigPk, message, sig, params, ctx: ctx);</code></pre>',
    )
    ..writeln('    </section>')
    ..writeln('    <section id="agents">')
    ..writeln('      <h2>Agent-ready context</h2>')
    ..writeln(
      '      <p>The same manifest generates the public AI discovery files and coding-agent rules, so assistants see the same boundaries humans see.</p>',
    )
    ..writeln('      <div class="cards">');

  for (final link in _primaryLinks(manifest)) {
    final url = link['url'] as String;
    buffer
      ..writeln(
        '        <a class="card" href="${_html(url.startsWith('http') ? url : url)}">',
      )
      ..writeln('          <strong>${_html(link['title'])}</strong>')
      ..writeln('          <span>${_html(link['description'])}</span>')
      ..writeln('        </a>');
  }

  buffer
    ..writeln('      </div>')
    ..writeln('    </section>')
    ..writeln('    <section id="docs">')
    ..writeln('      <h2>Canonical documentation</h2>')
    ..writeln('      <div class="cards docs">');

  for (final doc in docs) {
    buffer
      ..writeln(
        '        <a class="card" href="${_html(_repoBlob(project, doc['url'] as String))}">',
      )
      ..writeln('          <strong>${_html(doc['title'])}</strong>')
      ..writeln('          <span>${_html(doc['description'])}</span>')
      ..writeln('        </a>');
  }

  buffer
    ..writeln('      </div>')
    ..writeln('    </section>')
    ..writeln('  </main>')
    ..writeln('  <footer>')
    ..writeln(
      '    <span>Generated from <code>tool/visibility/visibility_manifest.json</code>.</span>',
    )
    ..writeln('    <a href="${_html(project['repository'])}">Repository</a>')
    ..writeln('    <a href="${_html(project['issues'])}">Issues</a>')
    ..writeln(
      '    <a href="${_html(project['security_advisory'])}">Security advisory</a>',
    )
    ..writeln('  </footer>')
    ..writeln('</body>')
    ..writeln('</html>');

  return buffer.toString();
}

