String _sitemap(JsonMap manifest) {
  final project = _map(manifest['project']);
  final base = project['canonical_url'] as String;
  final lastUpdated = manifest['last_updated'];
  final paths = [
    '',
    'llms.txt',
    'llms-full.txt',
    'identity.json',
    'developer-ai.txt',
    'faq-ai.txt',
    'ai.txt',
    'robots-ai.txt',
  ];
  final buffer = StringBuffer()
    ..writeln('<?xml version="1.0" encoding="UTF-8"?>')
    ..writeln('<!-- $_generatedNotice -->')
    ..writeln('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">');
  for (final path in paths) {
    buffer
      ..writeln('  <url>')
      ..writeln('    <loc>${_xml('$base$path')}</loc>')
      ..writeln('    <lastmod>$lastUpdated</lastmod>')
      ..writeln('  </url>');
  }
  buffer.writeln('</urlset>');
  return buffer.toString();
}

