    },
    {
      'title': 'developer-ai.txt',
      'url': '${base}developer-ai.txt',
      'description':
          'Coding-agent guidance for implementation and verification.',
    },
    {
      'title': 'faq-ai.txt',
      'url': '${base}faq-ai.txt',
