    },
  ];
}

String _repoBlob(JsonMap project, String path) {
  return '${project['repository']}/blob/${project['repository_branch']}/$path';
}

JsonMap _map(Object? value) => value as JsonMap;

List<JsonMap> _maps(Object? value) => (value as List).cast<JsonMap>();

List<String> _strings(Object? value) => (value as List).cast<String>();

String _mdComment() => '<!-- $_generatedNotice -->\n';

String _hashComment() => '# $_generatedNotice\n';

String _html(Object? value) {
  return value
      .toString()
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;');
}

String _xml(Object? value) {
  return _html(value).replaceAll("'", '&apos;');
}

String _scriptJson(Object value) {
  return jsonEncode(value)
      .replaceAll('<', r'\u003c')
      .replaceAll('>', r'\u003e')
      .replaceAll('&', r'\u0026');
}
